const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

module.exports = {
  config: {
    name: "نكح",
    aliases: ["nakah"],
    version: "1.0.2",
    author: "fadi",
    countDown: 3,
    role: 0,
    shortDescription: "إرسال رسالة بتكرار محدود",
    category: "fun",
    guide: "{pn} [1-50] أو {pn} stop"
  },

  onStart: async function ({ api, event, args }) {
    const threadID = event.threadID;

    if (args[0]?.toLowerCase() === "stop") {
      const task = activeTasks.get(threadID);

      if (!task) {
        return api.sendMessage(
          "ما كاين حتى إرسال خدام.",
          threadID
        );
      }

      task.stopped = true;
      return api.sendMessage(
        "تم طلب إيقاف الإرسال.",
        threadID
      );
    }

    if (activeTasks.has(threadID)) {
      return api.sendMessage(
        "كاين إرسال خدام. استعمل: نكح stop",
        threadID
      );
    }

    const count = Number.parseInt(args[0] || "1", 10);

    if (!Number.isInteger(count) || count < 1 || count > 50) {
      return api.sendMessage(
        "حدد العدد من 1 حتى 50.\nمثال: نكح 5\nللإيقاف: نكح stop",
        threadID
      );
    }

    // الحد الفعلي للإرسال التلقائي هو 10 رسائل
    const safeCount = Math.min(count, 10);
    const task = { stopped: false };
    activeTasks.set(threadID, task);

    try {
      for (let i = 0; i < safeCount; i++) {
        if (task.stopped) break;

        await new Promise(resolve => {
          api.sendMessage(MESSAGE, threadID, () => resolve());
        });

        if (i < safeCount - 1 && !task.stopped) {
          await sleep(3000);
        }
      }
    } finally {
      if (activeTasks.get(threadID) === task) {
        activeTasks.delete(threadID);
      }
    }
  }
};
